import{_ as t,V as e,W as o,X as l,Z as n,a1 as a,$ as c,Y as p,F as i}from"./framework-b1bd8911.js";const d={},u=n("blockquote",null,[n("p",null,'date-plugin 解决的是公历与农历互转的问题，比如给用户的订单时间打上"己亥年伍月壹捌"这种农历标签、做生肖营销、展示生辰八字风格的文案。纯 Java 实现，不依赖任何第三方库，也不依赖数据库——秘密在于它把农历规则编码成了两张整数表，查表即可完成互转。')],-1),r=p(`<p>本篇会先讲清楚&quot;查表法&quot;的实现原理，再手把手过一遍 <code>ChineseDateTool</code> / <code>ChineseDateExtendTool</code> 的用法和输出格式，最后把使用边界（支持哪些年份、闰月怎么判）交代清楚。</p><h2 id="i-农历互转的实现原理" tabindex="-1"><a class="header-anchor" href="#i-农历互转的实现原理" aria-hidden="true">#</a> I. 农历互转的实现原理</h2><p>农历是一套&quot;阴阳合历&quot;的体系，比公历麻烦得多：</p><ul><li>公历一年固定 12 个月、每月天数规则简单</li><li>农历的每个月是 29 天（小月）或 30 天（大月），由&quot;朔&quot;（月相）决定，没有规律可套公式</li><li>闰月的位置和几年一闰也不固定，遵循&quot;无中气置闰&quot;的规则</li><li>农历正月初一对应的公历日期，每年都不同</li></ul><p>所以 date-plugin 没有采用天文历法实时计算（那套东西的复杂度和出错率都很高），而是<strong>查表法</strong>：预先把 1887~2111 年的农历规则压缩编码，每个农历年占一个整数，共 225 项，转换时查表 + 位运算即可，快且不依赖任何外部资源。</p><h3 id="_1-两张核心表" tabindex="-1"><a class="header-anchor" href="#_1-两张核心表" aria-hidden="true">#</a> 1. 两张核心表</h3><p><code>ChineseDateTool</code> 里有两个关键的静态数组：</p><p><strong><code>lunar_month_days</code></strong>：每一项对应一个农历年（下标 0 对应 1887 年），记录了这一年农历每个月的天数和闰月信息，编码规则是：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>|----4位闰月|-------------13位1为30天，0为29天|
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><ul><li>高 4 位：当年的闰月是农历几月（比如 <code>0x6</code> 表示闰六月），为 0 表示当年没有闰月</li><li>低 13 位：从高位到低位依次表示第 1 到第 13 个月，为 1 表示 30 天的大月，为 0 表示 29 天的小月</li></ul><p><strong><code>solar_1_1</code></strong>：同样是每个农历年一项，编码的是&quot;当年农历正月初一对应的公历日期&quot;：</p><ul><li>12 位：公历年</li><li>4 位：公历月</li><li>5 位：公历日</li></ul><h3 id="_2-公历转农历" tabindex="-1"><a class="header-anchor" href="#_2-公历转农历" aria-hidden="true">#</a> 2. 公历转农历</h3><p>有了这两张表，公历转农历的思路就非常直白了，对应 <code>ChineseDateTool.solarToLunar</code>：</p><ol><li>先确定目标日期落在哪个农历年：取 <code>solar_1_1</code> 中&quot;正月初一小于等于目标日期&quot;的那一项</li><li>计算目标日期与当年正月初一之间的<strong>天数差</strong></li><li>从正月开始，逐月用&quot;该月是 30 天还是 29 天&quot;去扣减天数差，扣不动了就说明落在了当前月</li><li>最后根据闰月位置做修正：如果落在闰月之后，月序号要减 1，并给 <code>isleap</code> 标记赋值</li></ol><h3 id="_3-农历转公历" tabindex="-1"><a class="header-anchor" href="#_3-农历转公历" aria-hidden="true">#</a> 3. 农历转公历</h3><p>反过来，<code>ChineseDateTool.lunarToSolar</code> 就是正向累加：</p><ol><li>查表拿到当年闰月位置，按&quot;目标农历月在闰月之前还是之后&quot;确定要累加的月序范围</li><li>累加前面每个月的天数（30 或 29），再加上日</li><li>把这个天数偏移加到&quot;当年正月初一的公历日期&quot;上，直接得到目标公历日期</li></ol><p>整个转换没有任何浮点和迭代逼近，就是查表 + 位运算 + 累加，所以性能可以忽略不计。</p><blockquote><p>位运算的核心是 <code>getBitInt(data, length, shift)</code>：从整数的第 <code>shift</code> 位开始，取 <code>length</code> 位的值。两张表的编码和解析全靠它。</p></blockquote><h2 id="ii-依赖引入" tabindex="-1"><a class="header-anchor" href="#ii-依赖引入" aria-hidden="true">#</a> II. 依赖引入</h2><p>项目已发布到 maven 中央仓库，直接依赖即可，请注意使用最新版本：</p><div class="language-xml line-numbers-mode" data-ext="xml"><pre class="language-xml"><code><span class="token comment">&lt;!-- https://mvnrepository.com/artifact/com.github.liuyueyi.media/date-plugin --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>dependency</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>groupId</span><span class="token punctuation">&gt;</span></span>com.github.liuyueyi.media<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>groupId</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>artifactId</span><span class="token punctuation">&gt;</span></span>date-plugin<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>artifactId</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>version</span><span class="token punctuation">&gt;</span></span>3.1.0<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>version</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>dependency</span><span class="token punctuation">&gt;</span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>gradle 用户：</p><div class="language-groovy line-numbers-mode" data-ext="groovy"><pre class="language-groovy"><code><span class="token comment">// https://mvnrepository.com/artifact/com.github.liuyueyi.media/date-plugin</span>
implementation <span class="token string">&#39;com.github.liuyueyi.media:date-plugin:3.1.0&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>旧版本坐标为 <code>com.github.hui.media:date-plugin</code>，使用旧版本时需要额外引入作者的 maven 仓库源：</p><div class="language-xml line-numbers-mode" data-ext="xml"><pre class="language-xml"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>repositories</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>repository</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>id</span><span class="token punctuation">&gt;</span></span>yihui-maven-repo<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>id</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>url</span><span class="token punctuation">&gt;</span></span>https://raw.githubusercontent.com/liuyueyi/maven-repository/master/repository<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>url</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>repository</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>repositories</span><span class="token punctuation">&gt;</span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></blockquote><h2 id="iii-基础转换-chinesedatetool" tabindex="-1"><a class="header-anchor" href="#iii-基础转换-chinesedatetool" aria-hidden="true">#</a> III. 基础转换：ChineseDateTool</h2><p><code>ChineseDateTool</code> 提供了两个互逆的静态方法，以及两个数据载体类：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// 公历转农历</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">Lunar</span> <span class="token function">solarToLunar</span><span class="token punctuation">(</span><span class="token class-name">Solar</span> solar<span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 农历转公历</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">Solar</span> <span class="token function">lunarToSolar</span><span class="token punctuation">(</span><span class="token class-name">Lunar</span> lunar<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><code>Solar</code>：公历日期，三个字段 <code>solarYear</code>、<code>solarMonth</code>、<code>solarDay</code></li><li><code>Lunar</code>：农历日期，四个字段 <code>lunarYear</code>（农历年）、<code>lunarMonth</code>（农历月）、<code>lunarDay</code>（农历日）、<code>isleap</code>（是否闰月）</li></ul><p>直接看可运行的测试代码（对应测试类 <code>ChineseDateTest</code> 里的场景）：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@Test</span>
<span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">testDateTool</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 公历 2019-06-20</span>
    <span class="token class-name">ChineseDateTool<span class="token punctuation">.</span>Solar</span> solar <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ChineseDateTool<span class="token punctuation">.</span>Solar</span><span class="token punctuation">(</span><span class="token number">2019</span><span class="token punctuation">,</span> <span class="token number">6</span><span class="token punctuation">,</span> <span class="token number">20</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// 公历 -&gt; 农历</span>
    <span class="token class-name">ChineseDateTool<span class="token punctuation">.</span>Lunar</span> lunar <span class="token operator">=</span> <span class="token class-name">ChineseDateTool</span><span class="token punctuation">.</span><span class="token function">solarToLunar</span><span class="token punctuation">(</span>solar<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span>lunar<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token comment">// 输出: Lunar{isleap=false, lunarYear=2019, lunarMonth=5, lunarDay=18}</span>

    <span class="token comment">// 农历 -&gt; 公历（可逆验证）</span>
    <span class="token class-name">ChineseDateTool<span class="token punctuation">.</span>Solar</span> solar2 <span class="token operator">=</span> <span class="token class-name">ChineseDateTool</span><span class="token punctuation">.</span><span class="token function">lunarToSolar</span><span class="token punctuation">(</span>lunar<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span>solar2<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token comment">// 输出: Solar{solarYear=2019, solarMonth=6, solarDay=20}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>即公历 2019 年 6 月 20 日对应农历 2019 年五月十八，来回转换无损。</p><p>闰月的判断会体现在 <code>isleap</code> 上：假设某天落在闰四月，那么返回的 <code>Lunar</code> 中 <code>lunarMonth = 4</code>、<code>isleap = true</code>，业务代码里可以据此给月份加&quot;闰&quot;前缀。</p><h2 id="iv-中文输出-chinesedateextendtool" tabindex="-1"><a class="header-anchor" href="#iv-中文输出-chinesedateextendtool" aria-hidden="true">#</a> IV. 中文输出：ChineseDateExtendTool</h2><p><code>ChineseDateTool</code> 返回的是数字结构，直接展示给用户不友好。<code>ChineseDateExtendTool</code> 在它之上封装了一层中文输出，提供的方法如下：</p><table><thead><tr><th style="text-align:center;">方法</th><th style="text-align:center;">说明</th><th style="text-align:center;">输出示例</th></tr></thead><tbody><tr><td style="text-align:center;"><code>lunarYearToGanZhi(int lunarYear)</code></td><td style="text-align:center;">农历年份转干支纪年</td><td style="text-align:center;"><code>2019 -&gt; 己亥年</code></td></tr><tr><td style="text-align:center;"><code>lunarMonthToChinese(int month, boolean isleap)</code></td><td style="text-align:center;">农历月转中文，闰月加前缀</td><td style="text-align:center;"><code>5, false -&gt; 伍月</code></td></tr><tr><td style="text-align:center;"><code>lunarDayToChinese(int day)</code></td><td style="text-align:center;">农历日转中文</td><td style="text-align:center;"><code>18 -&gt; 壹捌</code></td></tr><tr><td style="text-align:center;"><code>hourToChinese(int hour)</code></td><td style="text-align:center;">24 小时制转十二时辰</td><td style="text-align:center;"><code>8 -&gt; 辰时</code></td></tr><tr><td style="text-align:center;"><code>parseLunar(Lunar)</code></td><td style="text-align:center;">Lunar 对象拼成中文字符串</td><td style="text-align:center;"><code>己亥年伍月壹捌</code></td></tr><tr><td style="text-align:center;"><code>getNowLunarDate(LocalDateTime, boolean containHour)</code></td><td style="text-align:center;">指定时间转农历描述，第二个参数控制是否带时辰</td><td style="text-align:center;"><code>己亥年伍月壹捌 辰时</code></td></tr><tr><td style="text-align:center;"><code>getNowLunarDate()</code></td><td style="text-align:center;">当前系统时间转生辰八字风格的农历描述</td><td style="text-align:center;"><code>己亥年伍月壹捌 辰时</code></td></tr><tr><td style="text-align:center;"><code>getLunarDateByTimestamp(long timestamp)</code></td><td style="text-align:center;">毫秒时间戳转农历描述</td><td style="text-align:center;"><code>己亥年伍月壹捌 辰时</code></td></tr></tbody></table><h3 id="_4-1-组合方法示例" tabindex="-1"><a class="header-anchor" href="#_4-1-组合方法示例" aria-hidden="true">#</a> 4.1 组合方法示例</h3><p>这是官方 readme 中的用例：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@Test</span>
<span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">testDate2Lunar</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token class-name">LocalDateTime</span> now <span class="token operator">=</span> <span class="token class-name">LocalDateTime</span><span class="token punctuation">.</span><span class="token function">now</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span>now <span class="token operator">+</span> <span class="token string">&quot;&gt;&gt;&gt;&quot;</span> <span class="token operator">+</span> <span class="token class-name">ChineseDateExtendTool</span><span class="token punctuation">.</span><span class="token function">getNowLunarDate</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span>now <span class="token operator">+</span> <span class="token string">&quot;&gt;&gt;&gt;&quot;</span> <span class="token operator">+</span>
            <span class="token class-name">ChineseDateExtendTool</span><span class="token punctuation">.</span><span class="token function">getLunarDateByTimestamp</span><span class="token punctuation">(</span>now<span class="token punctuation">.</span><span class="token function">toInstant</span><span class="token punctuation">(</span><span class="token class-name">ZoneOffset</span><span class="token punctuation">.</span><span class="token function">ofHours</span><span class="token punctuation">(</span><span class="token number">8</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">toEpochMilli</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>输出结果如下（以 2019-06-20 08:08 为例）：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token number">2019</span>-06-20T08:08:19.75<span class="token operator"><span class="token file-descriptor important">8</span>&gt;&gt;</span><span class="token operator">&gt;</span>己亥年伍月壹捌 辰时
<span class="token number">2019</span>-06-20T08:08:19.75<span class="token operator"><span class="token file-descriptor important">8</span>&gt;&gt;</span><span class="token operator">&gt;</span>己亥年伍月壹捌 辰时
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-2-各转换规则说明" tabindex="-1"><a class="header-anchor" href="#_4-2-各转换规则说明" aria-hidden="true">#</a> 4.2 各转换规则说明</h3><p><strong>干支纪年</strong>：公式是 <code>天干[(year-4)%10] + 地支[(year-4)%12] + &quot;年&quot;</code>，所以 2019 年取 <code>(2019-4)%10 = 5</code> 号天干&quot;己&quot;、<code>(2019-4)%12 = 11</code> 号地支&quot;亥&quot;，即&quot;己亥年&quot;。因为公式里固定减 4，传入的是<strong>农历年份</strong>而不是公历年份。</p><p><strong>农历月</strong>：1~10 月直接映射&quot;壹月~拾月&quot;，11、12 月为&quot;拾壹月&quot;、&quot;拾贰月&quot;；闰月在前面加前缀，输出形如&quot;润肆月&quot;（源码里的前缀字用的是&quot;润&quot;）。</p><p><strong>农历日</strong>：</p><table><thead><tr><th style="text-align:center;">农历日</th><th style="text-align:center;">输出</th></tr></thead><tbody><tr><td style="text-align:center;">1~10</td><td style="text-align:center;"><code>初壹</code> ~ <code>初拾</code></td></tr><tr><td style="text-align:center;">11~19</td><td style="text-align:center;"><code>壹壹</code> ~ <code>壹玖</code></td></tr><tr><td style="text-align:center;">20</td><td style="text-align:center;"><code>贰拾</code></td></tr><tr><td style="text-align:center;">21~29</td><td style="text-align:center;"><code>贰壹</code> ~ <code>贰玖</code></td></tr><tr><td style="text-align:center;">30</td><td style="text-align:center;"><code>叁拾</code></td></tr></tbody></table><p>注意输出风格是<strong>大写数字直拼</strong>（如&quot;壹捌&quot;），不是我们日常说的&quot;十八&quot;，这是为了贴合生辰八字/黄历的书写习惯。</p><p><strong>十二时辰</strong>：<code>hourToChinese(hour)</code> 的映射关系如下（与传统的两小时一个时辰一致，23 点和 0 点都算子时）：</p><table><thead><tr><th style="text-align:center;">时间</th><th style="text-align:center;">时辰</th><th style="text-align:center;">时间</th><th style="text-align:center;">时辰</th></tr></thead><tbody><tr><td style="text-align:center;">23点 / 0点</td><td style="text-align:center;">子时</td><td style="text-align:center;">12点</td><td style="text-align:center;">午时</td></tr><tr><td style="text-align:center;">1~2点</td><td style="text-align:center;">丑时</td><td style="text-align:center;">13~14点</td><td style="text-align:center;">未时</td></tr><tr><td style="text-align:center;">3~4点</td><td style="text-align:center;">寅时</td><td style="text-align:center;">15~16点</td><td style="text-align:center;">申时</td></tr><tr><td style="text-align:center;">5~6点</td><td style="text-align:center;">卯时</td><td style="text-align:center;">17~18点</td><td style="text-align:center;">酉时</td></tr><tr><td style="text-align:center;">7~8点</td><td style="text-align:center;">辰时</td><td style="text-align:center;">19~20点</td><td style="text-align:center;">戌时</td></tr><tr><td style="text-align:center;">9~10点</td><td style="text-align:center;">巳时</td><td style="text-align:center;">21~22点</td><td style="text-align:center;">亥时</td></tr><tr><td style="text-align:center;">11点</td><td style="text-align:center;">午时</td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table><h3 id="_4-3-手动组装输出" tabindex="-1"><a class="header-anchor" href="#_4-3-手动组装输出" aria-hidden="true">#</a> 4.3 手动组装输出</h3><p>如果转换和格式化想分开控制（比如只要&quot;己亥年五月十八&quot;、不要时辰），可以拆开用：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token class-name">ChineseDateTool<span class="token punctuation">.</span>Lunar</span> lunar <span class="token operator">=</span> <span class="token class-name">ChineseDateTool</span><span class="token punctuation">.</span><span class="token function">solarToLunar</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">ChineseDateTool<span class="token punctuation">.</span>Solar</span><span class="token punctuation">(</span><span class="token number">2019</span><span class="token punctuation">,</span> <span class="token number">6</span><span class="token punctuation">,</span> <span class="token number">20</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 只拼 年+月+日，不带时辰</span>
<span class="token class-name">String</span> text <span class="token operator">=</span> <span class="token class-name">ChineseDateExtendTool</span><span class="token punctuation">.</span><span class="token function">parseLunar</span><span class="token punctuation">(</span>lunar<span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// 己亥年伍月壹捌</span>

<span class="token comment">// 或者单独取干支年</span>
<span class="token class-name">String</span> ganZhi <span class="token operator">=</span> <span class="token class-name">ChineseDateExtendTool</span><span class="token punctuation">.</span><span class="token function">lunarYearToGanZhi</span><span class="token punctuation">(</span>lunar<span class="token punctuation">.</span><span class="token function">getLunarYear</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 己亥年</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="v-使用边界与注意点" tabindex="-1"><a class="header-anchor" href="#v-使用边界与注意点" aria-hidden="true">#</a> V. 使用边界与注意点</h2><ol><li><strong>支持年份范围是 1887~2111 年</strong>。查表的数组每个农历年一项，超出范围会直接数组越界，所以别拿它去算 2112 年之后的排期。</li><li><strong>只做日期维度，不处理节气、干支月/干支时</strong>。<code>hourToChinese</code> 输出的是&quot;地支时&quot;（如辰时），但年只有干支年，没有干支月，严格八字起盘的场景需要更专业的库。</li><li><strong><code>getLunarDateByTimestamp</code> 使用系统默认时区</strong>转 <code>LocalDateTime</code>，如果服务时区不是东八区，传入时间戳时请与 readme 示例一样显式换算（<code>toInstant(ZoneOffset.ofHours(8)).toEpochMilli()</code>），否则时辰可能差一档。</li><li><strong>闰月前缀是&quot;润&quot;</strong>，如果业务对用字敏感（&quot;闰&quot;才是标准写法），拿到 <code>lunarMonthToChinese</code> 的结果后可以自行替换。</li><li><strong>农历日的&quot;初一&quot;输出为&quot;初壹&quot;</strong>，同理&quot;十一&quot;是&quot;壹壹&quot;，做前端展示时如果习惯&quot;初一/十八&quot;的写法，需要再做一层映射。</li></ol><h2 id="vi-小结" tabindex="-1"><a class="header-anchor" href="#vi-小结" aria-hidden="true">#</a> VI. 小结</h2><p>本篇介绍了 date-plugin 的实现原理和完整用法：<code>ChineseDateTool</code> 用查表法（月天数表 + 正月初一对照表）完成公历与农历的互转，<code>ChineseDateExtendTool</code> 在其上封装了干支年、大写月日、十二时辰的中文输出，一行 <code>getNowLunarDate()</code> 就能得到 <code>己亥年伍月壹捌 辰时</code> 这样的结果。</p>`,57),k=n("strong",null,"项目地址：",-1),g={href:"https://github.com/liuyueyi/quick-media",target:"_blank",rel:"noopener noreferrer"};function m(h,v){const s=i("ExternalLinkIcon");return e(),o("div",null,[u,l(" more "),r,n("p",null,[k,a(),n("a",g,[a("https://github.com/liuyueyi/quick-media"),c(s)])])])}const b=t(d,[["render",m],["__file","01.公历与农历互转.html.vue"]]);export{b as default};
